effect.shader:
const int AMOSTRAS = 8;

/** O alfa num pixel com deslocamento em px (vai pra UV pela textura de entrada). */
float alfaEm(vec2 uv, vec2 deslocamentoPx) {
    vec2 tam = vec2(textureSize(inputImg, 0));
    return texture(inputImg, uv + deslocamentoPx / tam).a;
}

/**
 * A menor "proximidade do limite" nas 8 amostras em volta, no raio dado (px).
 * Retorna 0 = tudo opaco em volta; 1 = alguém ali está transparente.
 */
float probaForaNoRaio(vec2 uv, float raio) {
    float maximo = 0.0;
    for (int i = 0; i < AMOSTRAS; i++) {
        float a = 6.2831853 * (float(i) + 0.5) / float(AMOSTRAS);
        vec2 d = vec2(cos(a), sin(a)) * raio;
        float fora = 1.0 - alfaEm(uv, d);
        maximo = max(maximo, fora);
    }
    return maximo;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // Fora do alfa, o pixel não ganha borda.
    if (original.a < 1e-3) {
        fragColor = original;
        return;
    }

    // Dois raios: o INÍCIO da faixa (perto da quina) e o FIM (afastado por width+softness).
    // O `offset` empurra a faixa para dentro, saindo da quina.
    float raioInicio = max(offset, 0.5);
    float raioFim = raioInicio + max(width, 0.5);
    float extra = max(softness, 0.5);

    float noInicio = probaForaNoRaio(acScreenNorm, raioInicio);
    float noFim = probaForaNoRaio(acScreenNorm, raioFim + extra);

    // Dentro da faixa: inicio detecta algum vizinho fora, fim não vê mais nada fora.
    // (noInicio - noFim) dá o ANEL: alto no meio, zero nas duas pontas.
    float dentroDoAnel = clamp(noInicio - noFim, 0.0, 1.0);

    // A borda sempre pinta sobre o alfa original (não transborda).
    float forca = dentroDoAnel * opacity * original.a * borderColor.a;

    vec3 corDePintura = borderColor.rgb;
    vec3 saidaCor = mix(original.rgb, corDePintura, forca);

    fragColor = vec4(saidaCor, original.a);
}
